// Minimal cache utility to allow custom cache injection
// Default implementation uses a Map and simple TTL via setTimeout when ttl is provided.
class DefaultCache {
  constructor() {
    this.store = new Map();
    this.timers = new Map();
  }

  get(key) {
    return this.store.has(key) ? this.store.get(key) : undefined;
  }

  set(key, value, ttl) {
    this.store.set(key, value);
    if (this.timers.has(key)) {
      clearTimeout(this.timers.get(key));
      this.timers.delete(key);
    }
    if (typeof ttl === 'number' && ttl > 0) {
      const t = setTimeout(() => {
        this.store.delete(key);
        this.timers.delete(key);
      }, ttl);
      // Keep timer ref to allow clearing if overwritten
      this.timers.set(key, t);
    }
  }

  has(key) {
    return this.store.has(key);
  }

  del(key) {
    if (this.timers.has(key)) {
      clearTimeout(this.timers.get(key));
      this.timers.delete(key);
    }
    return this.store.delete(key);
  }

  clear() {
    for (const t of this.timers.values()) clearTimeout(t);
    this.timers.clear();
    this.store.clear();
  }
}

module.exports = {
  DefaultCache,
  getCache: (options) => {
    if (options && options.cache) return options.cache;
    if (!global.__GRS_DEFAULT_CACHE__) global.__GRS_DEFAULT_CACHE__ = new DefaultCache();
    return global.__GRS_DEFAULT_CACHE__;
  }
};
